import {
  DEFAULT_APP_CONFIG,
  LIMITS,
  STARTER_CATEGORIES,
  buildSearchKeywords,
  matchesAllTerms,
  parseSearchQuery,
  type AppConfig,
  type Category,
  type Wallpaper,
} from '@devdarshan/shared';
import { DEMO_CATEGORY_IDS, DEMO_WALLPAPER_ENTRIES } from './catalog.data';

/**
 * Demo catalogue, used only by DEMO builds (no Firebase project connected). It
 * holds original abstract artwork generated by scripts/demo, served from the
 * public repository's `demo-content` branch, so the app can be tried end to end:
 * browsing, search, preview, set wallpaper, download and share all use real
 * network images and the real native code paths.
 */

const BASE_URL = 'https://raw.githubusercontent.com/arghadeep752-commits/Gamesssssss/demo-content/wallpapers';

const starterById = new Map(STARTER_CATEGORIES.map((c) => [c.id, c]));

export const DEMO_CATEGORIES: Category[] = DEMO_CATEGORY_IDS.map((id) => starterById.get(id))
  .filter((c): c is (typeof STARTER_CATEGORIES)[number] => Boolean(c))
  .sort((a, b) => a.sortOrder - b.sortOrder)
  .map((c) => ({
    id: c.id,
    name: c.name,
    nameHi: c.nameHi,
    slug: c.id,
    description: c.description,
    sortOrder: c.sortOrder,
    isActive: true,
    wallpaperCount: DEMO_WALLPAPER_ENTRIES.filter((w) => w.categoryIds.includes(c.id)).length,
    coverUrl: null,
    coverThumbUrl: null,
    coverImagePath: null,
    coverThumbnailPath: null,
    coverPlaceholder: null,
    createdAt: null,
    updatedAt: null,
  }));

const categoryNames = new Map(DEMO_CATEGORIES.map((c) => [c.id, [c.name, c.nameHi]]));

export const DEMO_WALLPAPERS: Wallpaper[] = DEMO_WALLPAPER_ENTRIES.map((e) => ({
  id: e.id,
  title: e.title,
  description: 'Demo artwork. The real app shows wallpapers uploaded by DevDarshan admins.',
  categoryIds: [...e.categoryIds],
  tags: [...e.tags],
  status: 'published',
  requestedStatus: 'published',
  processing: 'ready',
  processingError: null,
  featured: false,
  originalUrl: `${BASE_URL}/${e.id}/original.jpg`,
  previewUrl: `${BASE_URL}/${e.id}/preview.webp`,
  thumbnailUrl: `${BASE_URL}/${e.id}/thumb.webp`,
  originalStoragePath: null,
  previewStoragePath: null,
  thumbnailStoragePath: null,
  width: e.width,
  height: e.height,
  aspectRatio: e.width / e.height,
  fileSizeBytes: e.bytes,
  mimeType: 'image/jpeg',
  placeholder: e.placeholder,
  dominantColor: e.dominantColor,
  imageVersion: 1,
  favoriteCount: 0,
  downloadCount: 0,
  searchKeywords: buildSearchKeywords({
    title: e.title,
    tags: e.tags,
    extra: e.categoryIds.flatMap((id) => categoryNames.get(id) ?? []),
  }),
  createdAt: e.publishedAt,
  updatedAt: e.publishedAt,
  publishedAt: e.publishedAt,
  processedAt: e.publishedAt,
  createdBy: null,
  updatedBy: null,
}));

const byId = new Map(DEMO_WALLPAPERS.map((w) => [w.id, w]));

export const DEMO_CONFIG: AppConfig = {
  ...DEFAULT_APP_CONFIG,
  featuredWallpaperIds: ['om-golden', 'trishul-kailash', 'morpankh-blue', 'kodanda', 'lotus-dawn', 'diya-deepavali'],
  featuredCategoryIds: ['mahadev', 'shri-krishna', 'shri-ram', 'shri-hanuman', 'maa-lakshmi', 'sanatan-symbols', 'hindu-temples'],
  festival: { enabled: true, title: 'Festival Collection', titleHi: 'त्योहार', categoryId: 'festival-wallpapers' },
};

export interface DemoPage {
  items: Wallpaper[];
  cursor: number | null;
}

function page(list: Wallpaper[], offset: number | null, pageSize: number): DemoPage {
  const start = offset ?? 0;
  const items = list.slice(start, start + pageSize);
  const next = start + items.length;
  return { items, cursor: next < list.length ? next : null };
}

export function demoLatestPage(offset: number | null, pageSize: number = LIMITS.pageSize): DemoPage {
  return page(DEMO_WALLPAPERS, offset, pageSize);
}

export function demoCategoryPage(categoryId: string, offset: number | null, pageSize: number = LIMITS.pageSize): DemoPage {
  return page(
    DEMO_WALLPAPERS.filter((w) => w.categoryIds.includes(categoryId)),
    offset,
    pageSize,
  );
}

export function demoSearch(input: string): Wallpaper[] {
  const parsed = parseSearchQuery(input);
  if (!parsed.term) return [];
  return DEMO_WALLPAPERS.filter((w) => matchesAllTerms(w.searchKeywords, parsed.terms));
}

export function demoWallpaper(id: string): Wallpaper | null {
  return byId.get(id) ?? null;
}

export function demoWallpapersByIds(ids: readonly string[]): { items: Wallpaper[]; missing: string[] } {
  const items: Wallpaper[] = [];
  const missing: string[] = [];
  for (const id of new Set(ids)) {
    const w = byId.get(id);
    if (w) items.push(w);
    else missing.push(id);
  }
  return { items, missing };
}
